-- Initial authoritative Brazilian state stamps. State boundaries are simplified
-- official IBGE API v3 meshes captured on 2026-08-25 and remain server-private.

insert into public.official_translation_keys(translation_key) values
  ('regionalStamps.espiritoSanto.name'),('regionalStamps.espiritoSanto.description'),('regionalStamps.espiritoSanto.alt'),('map.regions.espiritoSantoBrazil'),
  ('regionalStamps.minasGerais.name'),('regionalStamps.minasGerais.description'),('regionalStamps.minasGerais.alt'),('map.regions.minasGeraisBrazil'),
  ('regionalStamps.rioDeJaneiro.name'),('regionalStamps.rioDeJaneiro.description'),('regionalStamps.rioDeJaneiro.alt'),('map.regions.rioDeJaneiroBrazil'),
  ('regionalStamps.saoPaulo.name'),('regionalStamps.saoPaulo.description'),('regionalStamps.saoPaulo.alt'),('map.regions.saoPauloBrazil'),
  ('regionalStamps.parana.name'),('regionalStamps.parana.description'),('regionalStamps.parana.alt'),('map.regions.paranaBrazil'),
  ('inventory.sources.statePassage')
on conflict do nothing;

insert into public.official_assets(asset_key,asset_type) values
  ('stamp.state.espiritoSanto.front','collectibleThumbnail'),
  ('stamp.state.minasGerais.front','collectibleThumbnail'),
  ('stamp.state.rioDeJaneiro.front','collectibleThumbnail'),
  ('stamp.state.saoPaulo.front','collectibleThumbnail'),
  ('stamp.state.parana.front','collectibleThumbnail')
on conflict(asset_key) do nothing;

insert into public.official_asset_versions(
  asset_id,version,source,status,packaged_path,mime_type,width,height,byte_size,
  alt_text_key,is_decorative,author,metadata
)
select asset.id,1,'packaged','active',source.path,'image/webp',171,256,source.bytes,
  source.alt_key,false,'DUIF',jsonb_build_object('kind','collectibleThumbnail','territoryType','brazilState','stateCode',source.state_code)
from (values
  ('stamp.state.espiritoSanto.front','/assets/stamps/states/espirito-santo.webp',27372,'regionalStamps.espiritoSanto.alt','ES'),
  ('stamp.state.minasGerais.front','/assets/stamps/states/minas-gerais.webp',28030,'regionalStamps.minasGerais.alt','MG'),
  ('stamp.state.rioDeJaneiro.front','/assets/stamps/states/rio-de-janeiro.webp',27366,'regionalStamps.rioDeJaneiro.alt','RJ'),
  ('stamp.state.saoPaulo.front','/assets/stamps/states/sao-paulo.webp',20408,'regionalStamps.saoPaulo.alt','SP'),
  ('stamp.state.parana.front','/assets/stamps/states/parana.webp',28908,'regionalStamps.parana.alt','PR')
) source(asset_key,path,bytes,alt_key,state_code)
join public.official_assets asset on asset.asset_key=source.asset_key
where not exists(select 1 from public.official_asset_versions version where version.asset_id=asset.id and version.version=1);

