  ('10000000-0000-4000-8000-000000000032','state-stamp.espirito-santo','regionalStamps.espiritoSanto.name','regionalStamps.espiritoSanto.description','rare','stamp.state.espiritoSanto.front','active'),
  ('10000000-0000-4000-8000-000000000031','state-stamp.minas-gerais','regionalStamps.minasGerais.name','regionalStamps.minasGerais.description','rare','stamp.state.minasGerais.front','active'),
  ('10000000-0000-4000-8000-000000000033','state-stamp.rio-de-janeiro','regionalStamps.rioDeJaneiro.name','regionalStamps.rioDeJaneiro.description','rare','stamp.state.rioDeJaneiro.front','active'),
  ('10000000-0000-4000-8000-000000000035','state-stamp.sao-paulo','regionalStamps.saoPaulo.name','regionalStamps.saoPaulo.description','rare','stamp.state.saoPaulo.front','active'),
  ('10000000-0000-4000-8000-000000000041','state-stamp.parana','regionalStamps.parana.name','regionalStamps.parana.description','rare','stamp.state.parana.front','active')
on conflict(catalog_key) do update set
