-- Draft points are intentionally excluded from the point-radius materializer. They
-- provide the existing discovery UI/collection contract; the state polygon resolver
-- is the only function allowed to materialize them.
insert into public.route_reward_points(
  id,catalog_key,reward_item_id,latitude,longitude,eligibility_radius_km,kind,
  region_kind,region_label_key,title_key,description_key,inventory_category,status,sort_order
) values
