  ('20000000-0000-4000-8000-000000000035','state-stamp.sao-paulo','10000000-0000-4000-8000-000000000035',-22.19,-48.79,1,'stamp','state','map.regions.saoPauloBrazil','regionalStamps.saoPaulo.name','regionalStamps.saoPaulo.description','stamps','draft',303),
  ('20000000-0000-4000-8000-000000000041','state-stamp.parana','10000000-0000-4000-8000-000000000041',-24.89,-51.55,1,'stamp','state','map.regions.paranaBrazil','regionalStamps.parana.name','regionalStamps.parana.description','stamps','draft',304)
