drop policy if exists "Active route reward points are readable by authenticated players" on public.route_reward_points;
create policy "Readable route reward points" on public.route_reward_points for select to authenticated
using(status='active' or catalog_key like 'state-stamp.%');

alter table public.delivery_route_discoveries
  add column encounter_latitude double precision check(encounter_latitude between -90 and 90),
  add column encounter_longitude double precision check(encounter_longitude between -180 and 180);

create table public.brazil_state_boundary_imports(
  id uuid primary key default gen_random_uuid(),
  source text not null check(source='IBGE API v3'),
  version text not null,
  captured_at date not null,
  metadata jsonb not null default '{}'::jsonb,
  imported_at timestamptz not null default now(),
  unique(source,version)
);

create table public.brazil_state_boundaries(
  state_code text primary key check(state_code ~ '^[A-Z]{2}$'),
  ibge_code integer not null unique,
  name_key text not null references public.official_translation_keys(translation_key),
  import_id uuid not null references public.brazil_state_boundary_imports(id) on delete restrict,
  geometry extensions.geometry(MultiPolygon,4326) not null,
  reward_item_id uuid not null unique references public.reward_items(id),
  route_reward_point_id uuid not null unique references public.route_reward_points(id),
  active boolean not null default true,
  created_at timestamptz not null default now()
);
create index brazil_state_boundaries_geometry_idx on public.brazil_state_boundaries using gist(geometry);

create table public.profile_state_stamp_reservations(
  profile_id uuid not null references public.profiles(id) on delete cascade,
  state_code text not null references public.brazil_state_boundaries(state_code),
  delivery_id uuid not null references public.deliveries(id) on delete cascade,
  encountered_at timestamptz not null,
  collected_at timestamptz,
  created_at timestamptz not null default now(),
  primary key(profile_id,state_code)
);

alter table public.brazil_state_boundary_imports enable row level security;
alter table public.brazil_state_boundaries enable row level security;
alter table public.profile_state_stamp_reservations enable row level security;
revoke all on public.brazil_state_boundary_imports,public.brazil_state_boundaries,public.profile_state_stamp_reservations from public,anon,authenticated;
create policy "Owners read state stamp reservations" on public.profile_state_stamp_reservations
for select to authenticated using(profile_id=(select id from public.profiles where auth_user_id=auth.uid()));
grant select on public.profile_state_stamp_reservations to authenticated;

with imported as (
  insert into public.brazil_state_boundary_imports(source,version,captured_at,metadata)
  values('IBGE API v3','initial-southeast-parana-2026-08-25','2026-08-25',
    jsonb_build_object('quality','minima','stateSha256',jsonb_build_object(
      'ES','2e504bbe8957088f1c377243385377b48233353f2262a7f6ec9654b2f14bb736','MG','751096c0e6b04900b6ea0a464e593a32c5fe46da40f8945678608434011d1c3d','RJ','52a8b090d50baa637df63057deffb113c16cb13e12b884aff78a754923e4fef1','SP','f2a47dee2b8ad5a04f0e7bb6a6b4a0bfb08a6567c1949b617f41d54098cb0912','PR','6d2e09fc5ad49a6807e6d5bb2d14e693327459aee69d36f4e046c00d06683149')))
