  state_code,ibge_code,name_key,import_id,geometry,reward_item_id,route_reward_point_id
)
select source.state_code,source.ibge_code,
  case source.state_code
    when 'ES' then 'map.regions.espiritoSantoBrazil'
    when 'MG' then 'map.regions.minasGeraisBrazil'
    when 'RJ' then 'map.regions.rioDeJaneiroBrazil'
    when 'SP' then 'map.regions.saoPauloBrazil'
    when 'PR' then 'map.regions.paranaBrazil'
